import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{Gr as i,Jr as a,Kr as o,Yr as s,qr as c}from"./chunks/assets.DAjhvrpn.js";var l=JSON.parse(`{"title":"Air puffs","description":"","frontmatter":{"title":"Air puffs","lang":"en-US"},"headers":[],"relativePath":"building/air-puffs.md","filePath":"building/air-puffs.md"}`),u={name:`building/air-puffs.md`};function d(n,l,u,d,f,p){return e(),r(`div`,null,[...l[0]||=[t(`<h1 id="air-puffs" tabindex="-1">Air puffs <a class="header-anchor" href="#air-puffs" aria-label="Permalink to “Air puffs”">​</a></h1><p>The air puffs module has two main parts: air pressure regulation and valve control, and stimulus delivery.</p><figure><img src="`+s+`" alt="Air puffs module." width="1280" height="932" loading="lazy"><figcaption>Air puffs module.</figcaption></figure><h2 id="pressure-regulator-assembly" tabindex="-1">Pressure regulator assembly <a class="header-anchor" href="#pressure-regulator-assembly" aria-label="Permalink to “Pressure regulator assembly”">​</a></h2><ol><li>Remove the screw from the front of the miniature compressed air regulator (with the inlet down and the regulator screw on the right) and screw in the pressure gauge. Put the straight reducer, 3/8 x 1/8 NPT male, on the inlet of the regulator and a push-to-connect tube fitting for 3/8&quot; tube OD x 1/8 NPT male on the outlet. Then screw the assembly into the second outlet of the air supply manifold.</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Make sure to attach this assembly before screwing the air supply manifold to the T-slotted frame.</p></div><figure><img src="`+a+`" alt="" width="1280" height="932" loading="lazy"></figure><h2 id="control-manifold-assembly" tabindex="-1">Control manifold assembly <a class="header-anchor" href="#control-manifold-assembly" aria-label="Permalink to “Control manifold assembly”">​</a></h2><ol><li>Have a machine shop make the air puffs control manifold in aluminum. With the small 10-32 holes facing down, insert a hex drive plug, 1/8 NPTF, at the right end, a pair of 1/16&quot; tube ID x 10-32 male barbed tube fittings at the bottom, a push-to-connect tube fitting for 3/8&quot; tube OD x 1/8 NPT male at the left, and finally a pair of subminiature solenoid valves for air from Gems Sensors &amp; Controls (EG2020-06MM-B-G1-204).</li></ol><figure><img src="`+c+`" alt="" width="1280" height="932" loading="lazy"></figure><ol start="2"><li>Place a couple of 10-24 square nuts at the back of the manifold-to-DIN-rail-clip adapter; if needed, apply some pressure so they go all the way into the holes (you can use a hammer for this). Then use a couple of 6-32 x 1&quot; long screws to screw the manifold to the adapter. After that, use a couple of number 6 size, 1/4&quot; long thread-forming screws to attach a 75 mm DIN rail mounting clip to the adapter. Place the entire assembly into the bottom DIN rail, somewhere between the hole for the tubing and the air supply manifold.</li></ol><figure><img src="`+o+`" alt="" width="1280" height="932" loading="lazy"></figure><ol start="3"><li>Connect the manifold outputs to the tube fittings at the back of the spout holder inside the rig using Tygon PVC tubing for food, beverage and dairy, 1/16&quot; ID, 1/8&quot; OD. If you installed a hose and cable carrier, route the tubes through it.</li></ol><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><ol start="4"><li>Connect the valves to the proper outputs of the solenoid valve driver in the control module.</li></ol>`,15)]])}var f=n(u,[[`render`,d]]);export{l as __pageData,f as default};